#include "exgine/gles_ibl.hpp"
#include "exgine/gles_production_complete.hpp"
#include <unordered_map>
namespace exgine { namespace { std::unordered_map<const OpenGLESRenderer*,GpuIblResources> g_ibl; }
bool build_gpu_ibl(OpenGLESRenderer&r,const GlesCubeResource&s,std::uint32_t irradiance_size,std::uint32_t specular_size,std::uint32_t specular_mips,GpuIblResources&o,std::string&e)noexcept{o={};o.environment=s;if(!gpu_convolve_irradiance(r,s,irradiance_size,o.irradiance,e))return false;if(!gpu_prefilter_ggx(r,s,specular_size,specular_mips,o.specular,e))return false;o.valid=true;g_ibl[&r]=o;return true;}
bool bind_production_ibl(OpenGLESRenderer&r,GlUInt program)noexcept{auto it=g_ibl.find(&r);if(it==g_ibl.end()||!it->second.valid||!program)return false;auto&a=const_cast<OpenGLESApi&>(r.api());constexpr GlEnum CUBE=0x8513,T0=0x84C0;auto bind=[&](GlUInt tex,const char*name,int unit){if(!tex)return false;a.ActiveTexture(T0+GlEnum(unit));a.BindTexture(CUBE,tex);auto loc=a.GetUniformLocation(program,name);if(loc>=0)a.Uniform1i(loc,unit);return true;};bool ok=bind(it->second.environment.texture,"u_environment_map",8)&&bind(it->second.irradiance.texture,"u_ibl_irradiance",9)&&bind(it->second.specular.texture,"u_ibl_specular",10);auto loc=a.GetUniformLocation(program,"u_ibl_max_lod");if(loc>=0)a.Uniform1f(loc,float(it->second.specular.mip_levels?it->second.specular.mip_levels-1:0));loc=a.GetUniformLocation(program,"u_ibl_intensity");if(loc>=0)a.Uniform1f(loc,1.f);return ok;}
}